import { Order, OrderSnapshot } from '../../domain/order/Order';
import { OrderRepository } from '../../domain/order/OrderRepository';
import { OrderStatus } from '../../domain/order/OrderStatus';

/**
 * Stores snapshots rather than live entities, so changes only become
 * visible once a use case explicitly saves them.
 */
export class InMemoryOrderRepository implements OrderRepository {
  private readonly records = new Map<string, OrderSnapshot>();

  findById(id: string): Order | undefined {
    const record = this.records.get(id);
    return record ? Order.restore(record) : undefined;
  }

  findAll(): Order[] {
    return [...this.records.values()].map((record) => Order.restore(record));
  }

  findByStatus(status: OrderStatus): Order[] {
    return [...this.records.values()]
      .filter((record) => record.status === status)
      .map((record) => Order.restore(record));
  }

  save(order: Order): void {
    this.records.set(order.id, structuredClone(order.toSnapshot()));
  }
}

=====SOURCE-END=====

